(()=>{const $=id=>document.getElementById(id);let result;const sci=(v,unit)=>v.toExponential(3)+' '+unit;
function run(){try{result=OrchLab.run({mode:$('orMode').value,energyLog:+$('orEnergy').value,unitLog:+$('orUnit').value,countLog:+$('orCount').value,coherenceLog:+$('orCoherence').value,targetMs:+$('orTarget').value});const r=result;
$('orTau').textContent=sci(r.tauSeconds,'s');$('orTotal').textContent=sci(r.energyJ,'J');$('orRatio').textContent=r.ratio.toExponential(2);
$('orResult').textContent=r.ratio>=1?'The assumed coherence lifetime reaches or exceeds the proposed OR timescale. This meets only the displayed timescale comparison; it does not establish physical feasibility or consciousness.':'The assumed coherence lifetime is shorter than the proposed OR timescale. Under these assumptions, environmental decoherence would intervene before the proposed timescale.';
$('orExecuted').textContent=`Executed energy model: ${r.protocol.mode} · E_G = ${sci(r.energyJ,'J')} · assumed coherence ${sci(r.coherenceSeconds,'s')} · target ${r.protocol.targetMs} ms`;
$('orTargetResult').textContent=`For the chosen ${r.protocol.targetMs} ms target, the relation requires E_G ≈ ${sci(r.targetEnergyJ,'J')}. Under the optional additive assumption and e_G = ${sci(10**r.protocol.unitLog,'J')}, N ≈ ${r.requiredEffectiveUnits.toExponential(3)} effective contributions. This is an algebraic requirement, not a biological estimate.`;
const X=e=>55+(e+50)/30*610,Y=t=>25+(16-Math.log10(t))/32*210;const line=r.sweep.map((s,i)=>(i?'L':'M')+X(s.energyLog)+','+Y(s.tau)).join(' ');
$('orChart').innerHTML=`<svg viewBox="0 0 740 300" role="img" aria-label="Hypothesized OR timescale in seconds versus assumed gravitational self energy in joules; both axes logarithmic"><text x="55" y="14" fill="currentColor" font-size="12">OR timescale τ (seconds, log scale)</text>${[-16,-8,0,8,16].map(v=>`<line x1="55" x2="665" y1="${Y(10**v)}" y2="${Y(10**v)}" stroke="#334155"/><text x="0" y="${Y(10**v)+4}" fill="currentColor" font-size="12">10^${v}</text>`).join('')}<path d="${line}" stroke="#64d1e6" stroke-width="3" fill="none"/><line x1="55" x2="665" y1="${Y(r.coherenceSeconds)}" y2="${Y(r.coherenceSeconds)}" stroke="#ff866f" stroke-dasharray="6 4"/><line x1="55" x2="665" y1="${Y(r.targetSeconds)}" y2="${Y(r.targetSeconds)}" stroke="#b8a0e8" stroke-dasharray="2 4"/>${Math.log10(r.energyJ)>=-50&&Math.log10(r.energyJ)<=-20?`<circle cx="${X(Math.log10(r.energyJ))}" cy="${Y(r.tauSeconds)}" r="6" fill="#fff"/>`:''}${[-50,-40,-30,-20].map(v=>`<text x="${X(v)-15}" y="260" fill="currentColor" font-size="12">10^${v}</text>`).join('')}<text x="160" y="288" fill="currentColor" font-size="12">Assumed E_G (joules, log scale)</text></svg>`;
$('orStatus').textContent='Calculated from your assumptions. No experimental data fitted.';
$('orOffscale').textContent=r.energyJ<1e-50||r.energyJ>1e-20?'Selected energy is outside the plotted range; its numerical result is shown above.':'';
}catch(e){$('orStatus').textContent=e.message;}}
function mode(){const additive=$('orMode').value==='additive';$('orDirectFields').hidden=additive;$('orAdditiveFields').hidden=!additive;}
$('orMode').onchange=()=>{mode();$('orStatus').textContent='Energy model changed. Calculate to update results.';};$('orRun').onclick=run;$('orExport').onclick=()=>download('qualia-orch-assumptions.json',JSON.stringify(result,null,2));mode();run();})();
